'use strict';
const assert=require('node:assert/strict'),fs=require('node:fs'),{diagnose}=require('./factoredJudgeDiagnostic'),a=require('./factoredJudgeActual24'),historical=require('./pricingDirectiveGroupsActualJudge');
function returned(call){assert.equal(call.status,'returned');assert.equal(call.httpStatus,200);assert(!Object.hasOwn(call,'errorCode'));assert.equal(call.requestSha256,a.sha(call.request||''));assert.equal(call.responseSha256,a.sha(call.response));assert.equal(call.responseBytes,Buffer.byteLength(call.response));assert.equal(call.observedBytes,call.responseBytes);}
async function audit(result,doc,inputSha256){const rows=a.packets(doc),spec=a.phaseSpec(result.phase),selected=rows.slice(spec.start,spec.start+spec.count);assert.equal(result.protocol,a.PROTOCOL);assert.equal(result.semanticSha256,a.semanticDigest());assert.equal(result.inputSha256,inputSha256);assert.deepEqual(result.model,{name:historical.MODEL,digest:historical.DIGEST});assert.equal(result.status,'phase-complete-review-pending');assert.equal(result.technicalComplete,true);assert.equal(result.semanticAccepted,null);assert.equal(result.creditAuthorized,false);assert.deepEqual(result.unattempted,[]);assert.deepEqual(result.remainingPhaseUnattempted,result.phase==='simple6'?rows.slice(6).map(x=>x.id):[]);assert.deepEqual(result.cases.map(x=>x.id),selected.map(x=>x.id));assert(result.calls.length<=spec.http);result.calls.forEach((c,i)=>{assert.equal(c.index,i+1);returned(c);});const meta=result.calls[0];assert.equal(meta.kind,'metadata');assert.equal(meta.stage,null);assert.equal(meta.caseId,null);assert.equal(meta.request,null);assert.equal(JSON.parse(meta.response).models.find(x=>x.name===historical.MODEL)?.digest,historical.DIGEST);assert(result.calls.slice(1).every(x=>x.kind==='inference'&&selected.some(p=>p.id===x.caseId)));
 let offset=1;for(let i=0;i<selected.length;i++){const p=selected[i],row=result.cases[i];assert.equal(row.packetSha256,a.sha(JSON.stringify(p)));const calls=result.calls.filter(c=>c.caseId===p.id);assert(calls.length>=1&&calls.length<=6);assert.deepEqual(result.calls.slice(offset,offset+calls.length),calls);offset+=calls.length;let cursor=0;const {id,objective,effectRequired,...evidence}=p;const replay=await diagnose(evidence,{objective,effectRequired,transport:async request=>{const c=calls[cursor++];assert(c);assert.equal(c.stage,request.stage);const sent=JSON.parse(c.request);a.wireOptions(sent);assert.deepEqual(sent.messages,request.messages);assert.deepEqual(sent.format,request.format);return a.completeWire(c.response);}});assert.equal(cursor,calls.length);for(const key of ['protocol','verdict','reason','creditAuthorized','semanticAccepted','stages','requests','failures','wireAttemptsVerified'])assert.deepEqual(row.result[key],replay[key],key);const trace=x=>{const v=JSON.parse(JSON.stringify(x));for(const record of v.records)delete record.elapsedMs;return v;};assert.deepEqual(trace(row.result.transport),trace(replay.transport));assert.equal(row.result.transport.attempts,calls.length);assert.equal(row.result.transport.physicallyPending,false);const observed=row.result.transport.records.filter(x=>x.status!=='skipped-negative-requires-coverage');assert.equal(observed.length,calls.length);observed.forEach((record,j)=>{assert.equal(record.status,'observed-unvalidated');assert.equal(record.raw,a.completeWire(calls[j].response));assert.equal(record.responseSha256,a.sha(record.raw));assert.equal(record.stage,replay.transport.records.filter(x=>x.status!=='skipped-negative-requires-coverage')[j].stage);});}assert.equal(offset,result.calls.length);return {protocol:a.PROTOCOL,semanticSha256:a.semanticDigest(),phase:result.phase,inputSha256,mechanicalComplete:true,semanticAccepted:null,creditAuthorized:false,reviewRequired:'independent provisional semantic review; no credit'};}
async function main(){const [resultFile,inputFile,inputPin,out]=process.argv.slice(2);const fd=fs.openSync(resultFile,fs.constants.O_RDONLY|fs.constants.O_NOFOLLOW);let result;try{const size=fs.fstatSync(fd).size;assert(size<=a.ARTIFACT_BYTES);const bytes=Buffer.alloc(size+1);let n=0;while(n<bytes.length){const count=fs.readSync(fd,bytes,n,bytes.length-n,null);if(!count)break;n+=count;}assert.equal(n,size);result=JSON.parse(bytes.subarray(0,n));}finally{fs.closeSync(fd);}const doc=a.readPinned(inputFile,inputPin);let value;try{value=await audit(result,doc,inputPin);}catch{value={mechanicalComplete:false,semanticAccepted:null,creditAuthorized:false,reason:'wire-or-projection-invalid'};process.exitCode=1;}fs.writeFileSync(out,JSON.stringify(value)+'\n',{mode:0o600});}
module.exports={audit,returned};if(require.main===module)main().catch(()=>{console.error('Factored mechanical audit unavailable');process.exitCode=1;});
